 63	    {id:'friend-b',name:'친구 나',avatar:'나',incoming:'자료는 확인했어?',outgoing:'응, 확인했어.'},
 64	    {id:'study',name:'과제 스터디',avatar:'팀',incoming:'질문은 여기에 남겨 줘.',outgoing:'다음 모임 때 같이 보자.'},
 65	    {id:'friend-c',name:'친구 다',avatar:'다',incoming:'공부 끝나면 이야기하자.',outgoing:'알겠어.'}
 66	  ];
 67	  let selected = 'friend-a';
 68	  const drafts = {};
 69	  const list = root.querySelector('.q3-list');
 70	  const input = root.querySelector('textarea');
 71	  const saved = window.openai?.widgetState?.privateContent;
 72	  if (saved && people.some(p => p.id === saved.selected)) selected = saved.selected;
 73	  if (saved?.drafts && typeof saved.drafts === 'object') {
 74	    people.forEach(p => {if(typeof saved.drafts[p.id] === 'string') drafts[p.id] = saved.drafts[p.id].slice(0,1000);});
 75	  }
 76	  function persist(){
 77	    if(window.openai?.setWidgetState) window.openai.setWidgetState({modelContent:{selectedConversation:selected},privateContent:{selected,drafts}}).catch(()=>{});
 78	  }
 79	  function bubbles(container,p){
 80	    container.replaceChildren();
 81	    [p.incoming,p.outgoing].forEach((text,i)=>{const b=document.createElement('div');b.className='q3-bubble'+(i?' me':'');b.textContent=text;container.append(b);});
 82	  }
 83	  function render(){
 84	    const p=people.find(p=>p.id===selected);
 85	    root.querySelector('.q3-name').textContent=p.name;
 86	    bubbles(root.querySelector('.q3-messages'),p);
 87	    input.value=drafts[selected]||'';
 88	    list.querySelectorAll('button').forEach(b=>{const active=b.dataset.person===selected;b.setAttribute('aria-pressed',String(active));b.querySelector('.q3-person-state').textContent=active?'선택됨':'대화 열기';});
 89	  }
 90	  people.forEach(p=>{
 91	    const button=document.createElement('button');button.type='button';button.className='q3-person cursor-interaction';button.dataset.person=p.id;
 92	    const avatar=document.createElement('span');avatar.className='q3-avatar';avatar.textContent=p.avatar;avatar.setAttribute('aria-hidden','true');
 93	    const copy=document.createElement('span');copy.className='q3-person-copy';
 94	    const name=document.createElement('span');name.className='q3-person-name';name.textContent=p.name;
 95	    const state=document.createElement('span');state.className='q3-person-state';copy.append(name,state);button.append(avatar,copy);list.append(button);
 96	    button.addEventListener('click',()=>{drafts[selected]=input.value.slice(0,1000);selected=p.id;render();persist();});
 97	  });
 98	  input.maxLength=1000;
 99	  input.addEventListener('input',()=>{drafts[selected]=input.value;persist();});
100	  root.querySelector('.q3-detach').addEventListener('click',()=>{
101	    const p=people.find(p=>p.id===selected);const panel=root.querySelector('.q3-detached');panel.querySelector('h2').textContent=p.name+' · 별도 보기';bubbles(panel.querySelector('.q3-detached-content'),p);panel.hidden=false;panel.querySelector('button').focus();
102	  });
103	  root.querySelector('.q3-merge').addEventListener('click',()=>{root.querySelector('.q3-detached').hidden=true;root.querySelector('.q3-detach').focus();});
104	  window.addEventListener('openai:set_globals',event=>{
105	    const state=event.detail?.globals?.widgetState?.privateContent;
106	    if(state && people.some(p=>p.id===state.selected)){selected=state.selected;people.forEach(p=>{if(typeof state.drafts?.[p.id]==='string')drafts[p.id]=state.drafts[p.id].slice(0,1000);});render();}
107	  });
108	  render();
109	})();
110	</script>

